mapper.select:
/*selectMasterMdCmCmsItemList*/ SELECT CMS_CATLG_ID /* 상품정보코드 */ ,DECODE(STATUS, 'D', '미사용', '사용') AS STATUS_NM /* 상품상태 */ ,STATUS /* 상품상태(원값) */ ,DESCRIPTION_LOC /* 품목명 */ ,MODEL_INFO /* 모델번호 */ ,SPECIFICATION /* 규격 */ ,MAKER_NAME /* 제조사명 */ ,MAKER_CODE /* 제조사코드 */ ,(SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = ORIGIN_CODE) AS ORIGIN_CODE_NAME /* 원산지명 */ ,ORIGIN_CODE /* 원산지코드 */ ,ORDER_MEASURE /* 단위 */ ,DECODE(ITEM_GUBUN, 'G', '표준품', '비표준품') AS ITEM_GUBUN_NM /* 상품구분(ICOMCOD1 M118: A전용품/G표준품/M MAKER/S제작품) */ ,ITEM_GUBUN /* 상품구분(원코드) */ ,DECODE(NVL(ONETIME_YN,'N'), 'Y', '일회성', '일반') AS ONETIME_NM /* 일회성구분 (Y=일회성 / N·미입력=일반) */ ,(SELECT MD.TEXT1 FROM ICOMCOD1 MD WHERE MD.TYPE = 'M181' AND MD.CODE = CMSCATLG.TR_HANDLE_TYPE) AS TR_HANDLE_NM /* TR취급가능여부 */ ,(SELECT SG.SG_NAME FROM CMSCATEG CG, KEPSGMG SG WHERE CG.CMS_CATEG_ID = CMSCATLG.CMS_CATEG_ID AND CG.STATUS <> 'D' AND CG.SG_ID = SG.SG_ID) AS SG_NAME /* 카테고리(=SG명) */ ,(SELECT CG.SG_ID FROM CMSCATEG CG WHERE CG.CMS_CATEG_ID = CMSCATLG.CMS_CATEG_ID AND CG.STATUS <> 'D') AS SG_ID /* 카테고리(=SG코드) */ ,CMS_CATEG_ID /* 상세분류코드 */ ,(SELECT CATEG_NAME FROM CMSCATEG WHERE CMS_CATEG_ID = CMSCATLG.CMS_CATEG_ID AND STATUS <> 'D') AS CMS_CATEG_NAME /* 상세분류명(리프) */ /* 구매담당자 = 카테고리(SG) 담당 SM. 표시는 정담당(CMSM 1순위) 한 명 — CODE2='1' 이 SG 당 유일해서 스칼라로 안전하다. */ ,(SELECT MD.TEXT4 FROM CMSCATEG CG, ICOMCOD3 MD WHERE CG.CMS_CATEG_ID = CMSCATLG.CMS_CATEG_ID AND CG.STATUS <> 'D' AND MD.BUYER = 'KRKORE0001' AND MD.TYPE = 'CMSM' AND MD.CODE2 = '1' AND MD.FLAG = 'Y' AND MD.CODE1 = CG.SG_ID) AS KEP_USER_NAME /* 구매담당자(정담당 SM 이름) */ ,(SELECT MD.TEXT1 FROM CMSCATEG CG, ICOMCOD3 MD WHERE CG.CMS_CATEG_ID = CMSCATLG.CMS_CATEG_ID AND CG.STATUS <> 'D' AND MD.BUYER = 'KRKORE0001' AND MD.TYPE = 'CMSM' AND MD.CODE2 = '1' AND MD.FLAG = 'Y' AND MD.CODE1 = CG.SG_ID) AS KEP_USER_NO /* 구매담당자 USER_ID */ ,BASE_PRICE /* 기준가(원값 - 그리드 Float 포맷) */ ,(SELECT MD.TEXT1 FROM ICOMCOD1 MD WHERE MD.TYPE = 'M183' AND MD.CODE = CMSCATLG.BASE_PRICE_TYPE) AS BASE_PRICE_TYPE /* 기준가유형(명칭) */ /* 미사용 변경사유 : 상품상태가 '미사용'인 행에서만 노출 (사용 행은 공란) */ ,CASE WHEN STATUS = 'D' THEN (SELECT MD.TEXT1 FROM ICOMCOD1 MD WHERE MD.TYPE = 'M182' AND MD.CODE = CMSCATLG.CHANGE_REASON_CODE) ELSE '' END AS UNUSE_REASON /* 미사용 변경사유 */ /* 대체코드 : 변경사유가 '중복존재'(DUP)일 때만 노출 (그 외 사유는 공란) */ ,CASE WHEN STATUS = 'D' AND CHANGE_REASON_CODE = 'DUP' THEN ALT_CATLG_ID ELSE '' END AS ALT_CODE /* 대체코드 */ ,NVL(TRIM(MSDS_NO), TRIM(AC_NO)) AS CHEM_INFO_NO /* 화학물질정보 No.(MSDS 우선, 없으면 AC) */ ,(SELECT A.CMC_HARMFUL_YN FROM KEPMSDSHD A WHERE A.MSDS_NO = CMSCATLG.MSDS_NO) AS HARMFUL_YN /* 유해화학물질 */ ,MSDS_NO /* MSDS No.(원값 - 셀 클릭 분기용) */ ,AC_NO /* 안전확인대상 생활화학제품 No.(원값 - 셀 클릭 분기용) */ ,1 AS PRINT /* MSDS 등록·매핑 아이콘(SetImageList 1) */ ,5 AS ERASE_MSDS_NO /* MSDS 매핑해제 아이콘(SetImageList 5) */ ,DECODE(SAFE_STATUS, 'CERT', '인증', 'UNCERT', '미인증', 'EXCL', '비대상', '') AS SAFE_STATUS_NM /* 안전인증여부 : 공란(NONE·NULL)/인증/미인증/비대상 */ ,SAFE_TYPE /* 안전인증구분(KC/KCS/KFI) */ ,ADD_DATE /* 상품정보등록일(YYYYMMDD) */ ,NVL((SELECT 'Y' FROM CMSCATLG_HST H WHERE H.CMS_CATLG_ID = CMSCATLG.CMS_CATLG_ID AND ROWNUM = 1), 'N') AS HISTORY /* 변경이력 : 이력이 1건이라도 있으면 Y. PK 선두가 CMS_CATLG_ID 라 인덱스로 끝난다 */ ,CHANGE_DATE /* 최종변경일(YYYYMMDD) */ FROM CMSCATLG WHERE 1=1 -- AND STD_FLAG = 'M' /* 상품정보 조회 및 관리 */
AND NVL(STATUS,'C') != 'D'
AND STATUS = 'D'
AND CMS_CATLG_ID IN
UPPER(#{item})
AND CMS_CATLG_ID = UPPER(#{st_cmscatlg})
AND EXISTS (SELECT 1 FROM CMSCATEG CG WHERE CG.CMS_CATEG_ID = CMSCATLG.CMS_CATEG_ID AND CG.STATUS != 'D' AND CG.SG_ID IN
#{item}
)
AND CMS_CATEG_ID IN
#{item}
AND DESCRIPTION_LOC LIKE '%' || #{st_item_name} || '%'
AND MODEL_INFO LIKE '%' || #{st_model_info} || '%'
AND SPECIFICATION LIKE '%' || #{st_specification} || '%'
AND ITEM_GUBUN = 'G'
AND NVL(ITEM_GUBUN,'X') != 'G'
AND NVL(ONETIME_YN,'N') = #{st_onetime_yn}
AND MAKER_CODE = #{st_maker_code}
AND EXISTS (SELECT 1 FROM CMSCATEG CG, ICOMCOD3 MD WHERE CG.CMS_CATEG_ID = CMSCATLG.CMS_CATEG_ID AND CG.STATUS != 'D' AND MD.BUYER = 'KRKORE0001' AND MD.TYPE IN ('CMSM','CMDSM') AND MD.FLAG = 'Y' AND MD.CODE1 = CG.SG_ID AND UPPER(TRIM(MD.TEXT1)) = UPPER(#{st_kep_user_no}))
AND EXISTS (SELECT 1 FROM CMSCATEG CG, ICOMCOD3 MD WHERE CG.CMS_CATEG_ID = CMSCATLG.CMS_CATEG_ID AND CG.STATUS != 'D' AND MD.BUYER = 'KRKORE0001' AND MD.TYPE IN ('CMSM','CMDSM') AND MD.FLAG = 'Y' AND MD.CODE1 = CG.SG_ID AND MD.TEXT4 LIKE '%' || #{st_kep_user_name} || '%')
AND ( UPPER(TRIM(MSDS_NO)) IN
UPPER(#{item})
OR UPPER(TRIM(AC_NO)) IN
UPPER(#{item})
)
AND ( UPPER(TRIM(MSDS_NO)) = UPPER(#{st_chem_no}) OR UPPER(TRIM(AC_NO)) = UPPER(#{st_chem_no}) )
AND NVL((SELECT A.CMC_HARMFUL_YN FROM KEPMSDSHD A WHERE A.MSDS_NO = CMSCATLG.MSDS_NO),'N') = #{st_harmful_yn}
AND CHANGE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND ADD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
ORDER BY CMS_CATLG_ID

/*master.mdcm.getCmsItemChangeReasonCodeList*/ SELECT CODE, TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M182' AND FLAG = 'Y'
AND TEXT3 = #{st_reason_dir}
ORDER BY VALUE1

mapper.update:

/*updateMasterMdCmCmsItemBasePriceApply*/
UPDATE CMSCATLG
   SET BASE_PRICE      = TO_NUMBER(F_HST_CMSCATLG(CMS_CATLG_ID
                                                , 'BASE_PRICE'
                                                , #{st_new_price}
                                                , #{st_user_id}
                                                , #{st_reason_code}
                                                , #{st_new_type_nm}
                                                , NULL))
     , BASE_PRICE_TYPE = #{st_new_type}
     , CHANGE_USER_ID  = #{st_user_id}
     , CHANGE_DATE     = TO_CHAR(SYSDATE,'YYYYMMDD')
     , CHANGE_TIME     = TO_CHAR(SYSDATE,'HH24MISS')
 WHERE CMS_CATLG_ID = #{st_catlg_id}
   AND (BASE_PRICE IS NULL OR TO_NUMBER(#{st_new_price}) >= BASE_PRICE)


/*insertMasterMdCmCmsItemBasePriceReqHd*/
INSERT INTO KEPMGPHD (
   BUYER, PM_NO, STATUS, REG_DATE, CHANGE_DATE
 , REG_USER_ID, REG_USER_DEPT, GUBUN, CA_FLAG, SUBJECT, REMARK
) VALUES (
   #{st_com_code}, #{st_pm_no}, 'C', SYSDATE, SYSDATE
 , #{st_user_id}, #{st_user_dept}, #{st_gubun}, 'N', #{st_subject}, #{st_remark}
)


/*insertMasterMdCmCmsItemBasePriceReqDt*/
INSERT INTO KEPMGPDT (
   BUYER, PM_NO, PM_SEQ, STATUS, REG_DATE, CHANGE_DATE, REG_USER_ID
 , CMS_CATLG_ID
 , RE_BASE_PRICE, CH_BASE_PRICE
 , RE_BASE_PRICE_TYPE, CH_BASE_PRICE_TYPE
 , BASE_PRICE_CHANGE_REASON
)
SELECT #{st_com_code}, #{st_pm_no}, #{st_pm_seq}, 'C', SYSDATE, SYSDATE, #{st_user_id}
     , C.CMS_CATLG_ID
     , C.BASE_PRICE, TO_NUMBER(#{st_new_price})
     , C.BASE_PRICE_TYPE, #{st_new_type}
     , #{st_reason_code}
  FROM CMSCATLG C
 WHERE C.CMS_CATLG_ID = #{st_catlg_id}
